mapper.update:
UPDATE COMMUNITY_POST
SET VIEWS = VIEWS + 1
WHERE POST_IDX = #{postIdx}

mapper.delete:
DELETE FROM COMMUNITY_POST
WHERE POST_IDX = #{postIdx}
  AND USER_IDX = #{userIdx}

mapper.select:
SELECT COUNT(*)
FROM COMMUNITY_POST
WHERE POST_IDX = #{postIdx}
  AND USER_IDX = #{userIdx}

mapper.update:
UPDATE POST_COMMENT
SET CONTENTS   = #{contents},
    UPDATED_AT = NOW()
WHERE COMMENT_IDX = #{commentIdx}
  AND USER_IDX    = #{userIdx}

mapper.delete:
DELETE FROM POST_COMMENT
WHERE COMMENT_IDX = #{commentIdx}
  AND USER_IDX    = #{userIdx}

mapper.select:
SELECT COUNT(*)
FROM POST_COMMENT
WHERE COMMENT_IDX = #{commentIdx}
  AND USER_IDX    = #{userIdx}
